  const horizon=12,ymax=Math.max(40,Math.ceil(Math.max(manual*horizon,24+ongoing*horizon)/20)*20),payback=saving>0?24/saving:null;
  const x=w=>42+w*24,y=h=>229-h/ymax*186;
  const inside=payback!==null&&payback<=horizon;
  const tick=[0,ymax/2,ymax].map(h=>'<path d="M42 '+y(h)+'H330" stroke="#d4dfdd"/><text x="6" y="'+(y(h)+5)+'" font-size="18">'+h+'</text>').join('');
