  const crossing=inside?'<path d="M'+x(payback)+' '+y(manual*payback)+'V229" stroke="#526268" stroke-dasharray="3 4"/><circle cx="'+x(payback)+'" cy="'+y(manual*payback)+'" r="6" fill="white" stroke="#192d32" stroke-width="3"/>':'';
