  effortView.innerHTML='<figure style="margin:16px 0;padding:8px;border-radius:12px;background:#fff;color:#192d32"><svg viewBox="0 0 360 285" role="img" aria-label="Manual rises '+manual.toFixed(1)+' hours per week from zero; automation rises '+ongoing.toFixed(1)+' from 24. '+relation+'" data-payback-weeks="'+(payback===null?'never':payback.toFixed(1))+'" style="display:block;width:100%;max-width:540px;height:auto;margin:auto;fill:#192d32"><text x="42" y="19" font-size="18">Total hours spent</text>'+tick+regions+'<path d="M42 43V229H330" stroke="#546b70" fill="none"/><path data-effort-line="manual" d="M42 '+y(0)+'L330 '+y(manual*12)+'" stroke="#24699a" stroke-width="4" fill="none"/><path data-effort-line="automated" d="M42 '+y(24)+'L330 '+y(24+ongoing*12)+'" stroke="#945512" stroke-width="4" stroke-dasharray="8 5" fill="none"/><circle cx="42" cy="'+y(24)+'" r="5" fill="#945512"/><text x="51" y="'+(y(24)+20)+'" font-size="18" fill="#71430c">24 h build</text>'+crossing+xs+'<text x="255" y="274" font-size="18">Weeks</text></svg><figcaption><strong>Solid blue: manual, +'+manual.toFixed(1)+' h/week.</strong><br><strong>Dashed brown: automated, +'+ongoing.toFixed(1)+' h/week.</strong><br>'+relation+' At week 12: manual '+(manual*12).toFixed(1)+' h; automated '+(24+ongoing*12).toFixed(1)+' h. The vertical gap is total extra work or total work saved. The hours axis rescales to fit both lines.</figcaption></figure>';
