function paintQueue(){
function chips(items,cancel){return items.length?items.map((r,i)=>'<span class="deploy-run'+(cancel?' deploy-canceled':'')+'">'+(cancel?'<s>'+r+'</s>':r)+'</span>'+(!cancel&&i<items.length-1?'<span aria-hidden="true">→</span>':'')).join(''):'<span>Empty</span>';}
deployView.innerHTML='<p class="deploy-event">'+deployEvent+'</p><div class="deploy-comparison">'+['single','max'].map(policy=>{const s=deployStates[policy];return '<section class="deploy-policy '+(queuePolicy.value===policy?'is-selected':'')+'"><h3>'+(policy==='single'?'Default: one pending slot':'queue: max — keep both waiting runs')+'</h3><div class="deploy-lane"><div class="deploy-running"><strong>Deployment target</strong><small>Only one run at a time</small><div class="deploy-runs">'+chips(s.running?[s.running]:[],false)+'</div><strong>'+(s.running?'RUNNING':'IDLE')+'</strong></div><div class="deploy-waiting"><strong>Pending area</strong><small>'+(policy==='single'?'A new arrival replaces this slot.':'Leftmost waiting run goes next.')+'</small><div class="deploy-runs">'+chips(s.waiting,false)+'</div><span class="deploy-route">'+(s.waiting.length?'Next into target: '+s.waiting[0]:'No run waiting')+'</span></div></div><div class="deploy-exits"><span class="deploy-label">Canceled — removed from the queue:</span> '+chips(s.canceled,true)+'</div><div class="deploy-exits"><span class="deploy-label">Completed:</span> '+(s.completed.join(', ')||'None')+'</div></section>';}).join('')+'</div>';
const s=deployStates[queuePolicy.value];world.textContent=['Running: '+(s.running||'none'),'Pending: '+(s.waiting.join(',')||'none'),'Canceled: '+(s.canceled.join(',')||'none'),'Completed: '+(s.completed.join(',')||'none')].join('\n');enqueueRun.disabled=nextRun>3;finishRun.disabled=!Object.values(deployStates).some(s=>s.running);}
function resetDeploy(){deployStates={single:freshDeploy(),max:freshDeploy()};nextRun=2;deployEvent='R1 starts. Both pending areas are empty.';paintQueue();}
enqueueRun.onclick=()=>{if(nextRun>3)return;const r='R'+nextRun++,effects=[];for(const policy of ['single','max']){const s=deployStates[policy];if(!s.running){s.running=r;effects.push(policy+': '+r+' enters the idle target.');}else{const removed=policy==='single'?s.waiting.splice(0):[];s.canceled.push(...removed);s.waiting.push(r);effects.push(policy+': '+(removed.length?removed.join(', ')+' is canceled; ':'')+r+' waits.');}}deployEvent=r+' arrives at both lanes. '+effects.join(' ');paintQueue();};
finishRun.onclick=()=>{const effects=[];for(const policy of ['single','max']){const s=deployStates[policy];if(s.running){const old=s.running;s.completed.push(old);s.running=s.waiting.shift()||null;effects.push(policy+': '+old+' finishes; '+(s.running?s.running+' enters the target.':'target is idle.'));}}deployEvent=effects.join(' ')||'Both targets are idle.';paintQueue();};
resetQueue.onclick=resetDeploy;queuePolicy.onchange=resetDeploy;resetDeploy();

function drawPages(){const base=[[10,'A'],[10,'B'],[20,'C'],[30,'D']],size=pageScenario.value==='tie'?1:2,cursor=base[size-1],rows=pageScenario.value==='insert'?[[5,'X'],...base]:base,offset=rows.slice(size,size+size),keyset=rows.filter(r=>r[0]>cursor[0]||(r[0]===cursor[0]&&r[1]>cursor[1])).slice(0,size),timeOnly=rows.filter(r=>r[0]>cursor[0]).slice(0,size),delivered=base.slice(0,size).map(r=>r[1]),names=rs=>rs.map(r=>r[1]).join(','),isInsert=pageScenario.value==='insert';
pageView.innerHTML='<p><strong>Page 1 already delivered: '+delivered.join(', ')+'</strong>. '+(isInsert?'Now X arrives at time 5. Watch the positions change.':'No row is inserted in this scenario.')+'</p><table><caption>Same rows, before and after the second request</caption><thead><tr><th scope="col">Tuple</th><th scope="col">Old position</th><th scope="col">Now</th><th scope="col">Already sent?</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr class="'+(r[1]==='X'?'pg-insert ':delivered.includes(r[1])&&offset.some(o=>o[1]===r[1])?'pg-repeat ':'')+(r[1]===cursor[1]?'pg-cursor':'')+'"><td>('+r.join(',')+')</td><td>'+(base.findIndex(b=>b[1]===r[1])<0?'new':base.findIndex(b=>b[1]===r[1])+1)+'</td><td>'+(i+1)+'</td><td>'+(delivered.includes(r[1])?'Yes':'No')+'</td></tr>').join('')+'</tbody></table><p class="pg-bookmark">Gold line: the cursor is after ('+cursor.join(',')+'). This boundary follows the row’s values, not its position.</p><div class="pg-compare"><div class="pg-method"><strong>Count positions: OFFSET '+size+'</strong><p>Skip '+names(rows.slice(0,size))+', then take '+size+'.</p><div class="pg-results">'+names(offset)+'</div><p>'+(offset.some(r=>delivered.includes(r[1]))?'B is repeated: its new position is beyond the skip count.':'No repeat in this scenario.')+'</p></div><div class="pg-method"><strong>Seek after ('+cursor.join(',')+')</strong><p>Keep tuples greater than the bookmark, then take '+size+'.</p><div class="pg-results">'+names(keyset)+'</div><p>'+(pageScenario.value==='tie'?'(10,B) follows (10,A): equal time, greater ID.':'The cursor still follows B, so page 2 starts at C.')+'</p></div></div>'+(pageScenario.value==='tie'?'<p class="pg-bookmark">Broken shortcut: time &gt; 10 returns '+names(timeOnly)+'. It skips B because B also has time 10. The ID is the tie-breaker.</p>':'')+'<p class="pg-note">'+(isInsert?'X lies behind the cursor and is missed by this traversal. Keyset is not a snapshot or change stream.':'The table uses a tiny, ascending list with non-null values.')+'</p>';
world.textContent=['Cursor: ('+cursor.join(',')+')','Offset page 2: '+names(offset),'Keyset page 2: '+names(keyset),'Time-only page 2: '+names(timeOnly),'Rows inserted behind cursor are not included'].join('\n');}pageScenario.onchange=drawPages;drawPages();
